    (v_route, 'Żywiecká přehrada', 'Vodní plocha v Polsku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.72126, 19.20444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Valley%20of%20%C5%BBywieci.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Valley%20of%20%C5%BBywieci.jpg"}'::text[], 0, '{"en": {"name": "Żywiec Lake", "description": "Lake in Silesian Voivodeship, Poland. A body of water in Poland — a pleasant ride destination with waterside views."}, "de": {"name": "Żywiecer See", "description": "Stausee in Polen. Ein Gewässer in Polen — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Jezioro Żywieckie", "description": "Zbiornik retencyjny na rzece Sole koło Żywca. Akwen w Polsce — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Żywiecká přehrada", "description": "Meer in Polen. Een waterpartij in Polen — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Żywiecká přehrada", "description": "Una masa de agua en Polonia: un destino agradable con vistas al agua."}, "fr": {"name": "Żywiecká přehrada", "description": "Lac en Pologne. Un plan d''eau en Pologne — une belle destination avec vue sur l''eau."}, "uk": {"name": "Живецьке озеро", "description": "Штучне водосховище неподалік від міста Живець в Сілезькому воєводстві (Польща). Водойма в Польщі — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
