    (v_route, 'vodní nádrž Orlík', 'Vodní dílo na Vltavě. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.57833, 14.16444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Orl%C3%ADk%201.jpg"}'::text[], 0, '{"en": {"name": "Orlík Reservoir", "description": "Lake in the Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Orlík", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Orlík", "description": "Zbiornik retencyjny (Bohostice, Czechy). Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Orlík", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Orlík", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "réservoir d''Orlík", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Орлік", "description": "Водосховище. Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
