    (v_route, 'vodní nádrž Trnávka', 'Česká vodní nádrž. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.5228, 15.2118, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%BDeliv%20%282%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20%C5%BDeliv%20%282%29.jpg"}'::text[], 1, '{"en": {"name": "Trnávka Reservoir", "description": "Czech reservoir. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "vodní nádrž Trnávka", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "vodní nádrž Trnávka", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "vodní nádrž Trnávka", "description": "Stuwmeer in Želiv, Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "vodní nádrž Trnávka", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "vodní nádrž Trnávka", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "vodní nádrž Trnávka", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
